public static class AgentCatalog38
{
 public static string Corporation(string station)=>DemoWorld.Systems.First(s=>s.Id==station).Faction=="Unclaimed"?"Frontier Contract Bureau":DemoWorld.Systems.First(s=>s.Id==station).Faction;
 public static string Faction(string corporation)=>corporation switch {"Free Stations"=>"Boreal Federation","Khepri Bulk"=>"Suryavarta Empire","Prospector League"=>"Kepler Resource Group","Syndicate Survey Office"=>"Syndicate of Worlds","Black Horizon Security"=>"Syndicate of Worlds",_=>"Concord of Worlds"};
 public static readonly Agent38[] Agents=DemoWorld.Systems.SelectMany(s=>Enum.GetValues<AgentDivision38>().SelectMany(d=>Enumerable.Range(1,4).Select(l=>new Agent38(s.Id+"/"+d+"/"+l,(d==AgentDivision38.Security?"Marshal ":d==AgentDivision38.Mining?"Surveyor ":"Dispatcher ")+s.Name.Split(' ')[0]+" "+new[]{"Asha","Ren","Mira","Sol"}[l-1],Corporation(s.Id),Faction(Corporation(s.Id)),s.Id,l,d)))).ToArray();
 public static readonly Dictionary<string,MissionDefinition38> Missions=Load();
 static Dictionary<string,MissionDefinition38> Load(){string path=Path.Combine(AppContext.BaseDirectory,"Assets","Missions38.json");var list=JsonSerializer.Deserialize<List<MissionDefinition38>>(File.ReadAllText(path),WeaponCatalog.JsonOptions)??[];foreach(var mission in list){mission.Name=Retheme41.Text(mission.Name);mission.Briefing=Retheme41.Text(mission.Briefing);foreach(var enemy in mission.EnemyWaves.SelectMany(w=>w))enemy.Name=Retheme41.Text(enemy.Name);}list.Add(new(){Id="l_relay",Name="Relay recovery",Division=AgentDivision38.Security,Level=1,Volume=1,Objective="Retrieve",Pockets=2,Waves=[4],Coverage="Authored L",Source="Starlight authored operation",Briefing="Destroy the relay commander to unlock the gate. Optional escorts may survive. Recover the physical dispatch from the inner pocket and return it to your agent. Approaching the relay can trigger capacitor-hunting reinforcements."});list.AddRange(MissionCatalogM.Load());return list.ToDictionary(m=>m.Id);}
 public static readonly string[] Factions=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Assets","Factions.json"))).RootElement.EnumerateArray().Select(e=>e.GetProperty("Name").GetString()!).Concat(Agents.Select(a=>a.Faction)).Distinct().OrderBy(s=>s).ToArray();
 public static double Required(int level)=>level switch{1=>-10,2=>1,3=>3,4=>5,_=>7};
}
