 public double RawStanding38(string entity)=>AgentsState.Standings.GetValueOrDefault(entity);
 public double EffectiveStanding38(string entity){if(!AgentsState.Standings.ContainsKey(entity))return 0;double raw=RawStanding38(entity);int level=Player.SkillLevel(raw<0?"Diplomacy":CriminalEntity38(entity)?"Criminal Connections":"Connections");return Math.Clamp(raw+(10-raw)*.04*level,-10,10);}
 bool CriminalEntity38(string entity){var a=WorldAgents44.FirstOrDefault(a=>a.Id==entity||a.Corporation==entity);return new[]{"Pale Orchard","Iron Lantern Cooperative","The Broken Wheel","Gravewind Cartel","Concordance of One","The Black Relay"}.Contains(Stations44.Name(a?.Faction??entity));}
 public void ChangeStanding38(string entity,double percent,string reason,double? cap=null){double before=RawStanding38(entity);if(percent>0)percent*=1+.05*Player.SkillLevel("Social");double after=Math.Clamp(before+((percent>=0?10:-10)-before)*Math.Abs(percent),-10,10);if(cap.HasValue)after=percent>=0?before>=cap?before:Math.Min(after,cap.Value):before<=cap?before:Math.Max(after,cap.Value);AgentsState.Standings[entity]=after;if(entity=="Concord of Worlds")ConcordStanding=(float)after;if(entity=="Syndicate of Worlds")SyndicateStanding=(float)after;AgentsState.History.Add(new(Now,entity,reason,before,after,percent));if(AgentsState.History.Count>1000)AgentsState.History.RemoveAt(0);}
 public bool CanUseAgent38(Agent38 a)=>a.Level==1||new[]{a.Id,a.Corporation,a.Faction}.All(e=>EffectiveStanding38(e)>-2)&&new[]{a.Id,a.Corporation,a.Faction}.Max(EffectiveStanding38)>=AgentCatalog38.Required(a.Level);
 public void InitializeAgents38(){AgentsState=new();AgentsState.Standings["Concord of Worlds"]=ConcordStanding;AgentsState.Standings["Syndicate of Worlds"]=SyndicateStanding;}
 public string RequestMission38(string agentId,DateTime? clock=null)
 {
  DateTime now=clock??Now;UpdateMissions38(now);var a=WorldAgents44.FirstOrDefault(a=>a.Id==agentId);if(a==null)return "Unknown agent.";if(!Docked||StationKey44!=a.Station)return "Dock at the agent's station to request work.";if(!CanUseAgent38(a))return "Insufficient effective standing or a relationship is -2 or lower.";if(AgentsState.Missions.Any(m=>m.Agent==a.Id&&m.State is "Offered" or "Accepted"))return "This agent already has an outstanding mission.";
  string next="";var previous=AgentsState.Missions.LastOrDefault(m=>m.Agent==a.Id&&m.State=="Completed");if(previous!=null&&previous.Spec.Part<previous.Spec.Parts)next=AgentCatalog38.Missions.Values.FirstOrDefault(d=>d.Chain==previous.Spec.Chain&&d.Part==previous.Spec.Part+1&&d.Level==a.Level)?.Id??"";
  var pool=AgentCatalog38.Missions.Values.Where(d=>d.Level==a.Level&&d.Division==a.Division&&d.Coverage!="Indexed"&&d.Coverage!="Authored L"&&d.ProfileM==null&&d.Part==1).OrderBy(d=>d.Id).ToArray();if(pool.Length==0)return "No authored missions available for this division and level.";int seq=AgentsState.OfferSequence.GetValueOrDefault(a.Id);var spec=next.Length>0?AgentCatalog38.Missions[next]:pool[seq%pool.Length];AgentsState.OfferSequence[a.Id]=seq+1;
  string dest=ImportedWorld43?ImportedMissionDestination44(a):Systems.Where(s=>s.Id!=SystemId&&(a.Level<4||s.Region!=Current.Region)).OrderBy(s=>JumpDistance(SystemId,s.Id)).ThenBy(s=>s.Id).Select(s=>s.Id).First();if(dest.Length==0)return "No reachable station destination is available.";
  decimal reward=(decimal)(80*Math.Pow(4,a.Level-1))*(1+.05m*Player.SkillLevel("Negotiation"));var m=new Mission38{Agent=a.Id,Definition=spec.Id,Pickup=StationKey44,Destination=spec.Division==AgentDivision38.Distribution?dest:StationKey44,SiteSystem=SystemId,Offered=now,Expires=now.AddDays(7),Reward=reward,Bonus=reward/2,LP=(int)(20*Math.Pow(4,a.Level-1)*(1+.1*Player.SkillLevel(a.Division+" Connections")))};AgentsState.Missions.Add(m);EnsureMissionL(m);return "";
 }
 public string AcceptMission38(string id,DateTime? clock=null){DateTime now=clock??Now;UpdateMissions38(now);var m=AgentsState.Missions.FirstOrDefault(m=>m.Id==id);if(m==null||m.State!="Offered")return "Offer unavailable.";if(!Docked||StationKey44!=m.Contact.Station)return "Dock at the agent station to accept.";if(!m.Storyline&&!CanUseAgent38(m.Contact))return "Agent standing requirements are no longer met.";decimal collateral=m.ProfileM?.Collateral??0;if(Balance<collateral)return "Insufficient funds for courier collateral.";if(collateral>0){WalletChange(-collateral,"Mission collateral escrow");m.CollateralHeldM=collateral;}m.State="Accepted";m.Accepted=now;m.Expires=now.AddDays(7);m.BonusUntil=now.AddHours(m.Spec.Level+1);var run=EnsureMissionL(m);run.Started=now;run.Expires=m.Expires;run.Entered[m.Pocket]=now;if(m.Spec.Division==AgentDivision38.Distribution)m.Hangars[m.Pickup]=m.Spec.Volume;return "";}
 public string DeclineMission38(string id,DateTime? clock=null){DateTime now=clock??Now;UpdateMissions38(now);var m=AgentsState.Missions.FirstOrDefault(m=>m.Id==id);if(m==null||m.State!="Offered")return "Only an offer can be declined.";if(!Docked||StationKey44!=m.Contact.Station)return "Dock at the agent station to decline.";if(AgentsState.Declines.TryGetValue(m.Agent,out var last)&&now-last<TimeSpan.FromHours(4))Penalty38(m,"Repeated decline",.005);AgentsState.Declines[m.Agent]=now;m.State="Declined";UpdateChainsM();return "";}
 void Penalty38(Mission38 m,string reason,double amount){ChangeStanding38(m.Agent,-amount,reason);ChangeStanding38(m.Contact.Corporation,-amount,reason);if(m.Storyline)FactionGain38(m.Contact.Faction,-amount,reason);}
 public string QuitMission38(string id){var m=AgentsState.Missions.FirstOrDefault(m=>m.Id==id);if(m==null||m.State!="Accepted")return "No accepted mission.";Penalty38(m,"Mission abandoned",.02);m.State="Failed";if(m.GraphL!=null){m.GraphL.State="Failed";m.GraphL.Failure="Mission abandoned";}m.Cargo=0;m.Hangars.Clear();UpdateChainsM();return "";}
 public void UpdateMissions38(DateTime now){foreach(var m in AgentsState.Missions.Where(m=>m.State is "Offered" or "Accepted"&&now>=m.Expires).ToArray()){if(m.State=="Accepted"){Penalty38(m,"Mission deadline expired",.02);m.Cargo=0;m.Hangars.Clear();}m.State="Expired";if(m.GraphL!=null){m.GraphL.State="Expired";m.GraphL.Failure="Mission deadline expired";}}}
 public string TransferMissionCargo38(string id,bool load,float volume){var m=AgentsState.Missions.FirstOrDefault(m=>m.Id==id);if(!Docked||m==null||m.State!="Accepted"||!float.IsFinite(volume)||volume<=0)return "Dock with an active mission and choose a positive amount.";float available=load?m.Hangars.GetValueOrDefault(StationKey44):m.Cargo;if(volume>available+.001f)return "Insufficient mission cargo.";string category=m.Spec.Division==AgentDivision38.Mining?m.Spec.Resource:"mission-freight";if(load&&volume>CargoRoom(category)+.001f)return "Not enough cargo capacity. Split the shipment into multiple trips.";m.Cargo+=load?volume:-volume;m.Hangars[StationKey44]=m.Hangars.GetValueOrDefault(StationKey44)+(load?-volume:volume);return "";}
 public float MissionCargoVolume38=>AgentsState.Missions.Sum(m=>m.Cargo);
 public string CompleteMission38(string id,DateTime? clock=null)
 {
  DateTime now=clock??Now;UpdateMissions38(now);var m=AgentsState.Missions.FirstOrDefault(m=>m.Id==id);if(m==null||m.State!="Accepted")return "No accepted mission.";if(!Docked||StationKey44!=m.Destination)return "Dock at the delivery station.";float quantity=m.Cargo+m.Hangars.GetValueOrDefault(StationKey44);if(m.Spec.Volume>0&&quantity+.001f<m.Spec.Volume)return "Required mission cargo is missing.";if((m.Spec.Division==AgentDivision38.Security||m.ProfileM?.Mode=="Task")&&!m.ObjectiveDone)return "Mission objective is not complete.";
  if(m.Spec.Volume>0){float take=Math.Min(m.Cargo,m.Spec.Volume);m.Cargo-=take;m.Hangars[StationKey44]=Math.Max(0,m.Hangars.GetValueOrDefault(StationKey44)-(m.Spec.Volume-take));}EnsureMissionL(m);m.State="Completed";StorageAt(StationKey44)["d_tag"]=StorageAt(StationKey44).GetValueOrDefault("d_tag")+1;HistoryD("Mission service tag earned / "+m.Id);EnsureMissionL(m).Emit("delivery");EnsureMissionL(m).Pump(now);SettleMissionL(m,now);if(m.CollateralHeldM>0){WalletChange(m.CollateralHeldM,"Courier collateral returned");m.CollateralHeldM=0;}UpdateChainsM();
  if(m.ChainRunM.Length>0)return "";if(m.Storyline)FactionGain38(m.Contact.Faction,.02*m.Spec.Level,"Storyline completed");else QualifyStorylineM(m,now);return "";
 }
 public void FactionGain38(string faction,double gain,string reason){ChangeStanding38(faction,gain,reason);var relations=new Dictionary<string,(string Friend,string Enemy)>{{"Boreal Federation",("Azadi Confederation","Suryavarta Empire")},{"Azadi Confederation",("Boreal Federation","Suryavarta Empire")},{"Suryavarta Empire",("Syndicate of Worlds","Azadi Confederation")},{"Syndicate of Worlds",("Suryavarta Empire","Concord of Worlds")},{"Concord of Worlds",("Boreal Federation","Syndicate of Worlds")}};if(relations.TryGetValue(Stations44.Name(faction),out var r)){string Key(string name)=>ImportedWorld43?Retheme41.Records.FirstOrDefault(p=>p.Key.StartsWith("faction:")&&p.Value.Name==name).Key??name:name;ChangeStanding38(Key(r.Friend),gain*.5,"Derived: "+reason,gain>0?5:-5);if(gain>0)ChangeStanding38(Key(r.Enemy),-gain*.5,"Derived: "+reason,-5);}}
 public bool MissionWarpTarget38(string id,out SpacePosition position){var m=AgentsState.Missions.FirstOrDefault(m=>m.WarpId==id&&m.State=="Accepted"&&m.SiteSystem==SystemId);position=m==null?default:SolarCatalog.Resolve(SystemId,ImportedWorld43?m.Contact.Station:"station")!.Anchor+new SpacePosition(SolarCatalog.AU*(.03+m.Id.Sum(c=>(int)c)%97*.0001),0,SolarCatalog.AU*(.01+m.Id.Sum(c=>(int)c)%71*.0001));return m!=null&&m.Spec.Division!=AgentDivision38.Distribution;}
