 void PopulateMission38(Mission38 m){if(m.Spec.Division==AgentDivision38.Mining&&m.Harvested<m.Spec.Volume){float ore=Math.Max(0,m.Spec.Volume-m.Harvested);if(ore>0)Targets.Add(new(){Id=m.WarpId+":resource",Name=m.Spec.Name+" / contract "+m.Spec.Resource,Kind=TargetKind.Asteroid,Resource=m.Spec.Resource,Ore=ore,Position=new(1800,0,0),Signature=300});}if(m.Spec.Division==AgentDivision38.Security||m.Spec.Hostiles){int count=m.Spec.Waves[Math.Min(m.Wave,m.Spec.Waves.Length-1)];for(int i=0;i<count;i++){string id=$"{m.WarpId}:{m.Pocket}:{m.Wave}:{i}";if(m.Kills.Contains(id))continue;float hp=60*MathF.Pow(3,m.Spec.Level-1);var npc=MakeRaider(new Vector3(3000+i*1400,300*(i%2),i*850));npc.Id=id;var spawn=m.Spec.EnemyWaves.ElementAtOrDefault(m.Wave)?.SelectMany(e=>Enumerable.Repeat(e,e.Count)).ElementAtOrDefault(i);npc.Name=spawn==null?"Contract hostile "+(i+1):"Contract "+spawn.Hull+" "+(i+1);if(spawn!=null){string hull=spawn.Hull switch{"Battleship"=>"battleship","Battlecruiser"=>"battlecruiser","Cruiser"=>"cruiser","Destroyer"=>"destroyer",_=>"frigate"};npc.Profile=new Ship();npc.Profile.SetCombatHull(hull);hp=Math.Max(hp,npc.Profile.MaxHull*.5f);npc.Signature=(float)npc.Profile.Stat("signatureRadius");}npc.Shield=hp;npc.Armor=hp*.6f;npc.Hull=hp*.5f;if(m.Spec.Objective=="Structure"&&i==0){npc.Name="Hostile installation";npc.Signature=3000;npc.Profile=null;}Targets.Add(npc);}}if(m.Spec.Objective=="Retrieve"&&m.ObjectiveDone&&m.Cargo+m.Hangars.Values.Sum()<m.Spec.Volume)Targets.Add(new(){Id=m.WarpId+":objective",Name="Contract objective",Kind=TargetKind.Container,Position=new(2000,0,0)});if(m.Spec.Pockets>1)Targets.Add(new(){Id=m.WarpId+":gate",Name="Acceleration gate",Kind=TargetKind.Celestial,Position=new(9000,0,0),Signature=2000});}
 public string AdvanceMissionPocket38(string id)=>AdvanceMissionGateL(id);
