 public float HarvestMission38(SpaceTarget t,float volume){var m=AgentsState.Missions.FirstOrDefault(m=>m.State=="Accepted"&&(t.Id==m.WarpId+":resource"||t.Id.StartsWith(m.WarpId+":resource:")));if(m==null)return 0;float amount=Math.Min(volume,Math.Min(t.Ore,CargoRoom(m.Spec.Resource)));if(m.Spec.Resource=="ice")amount=MathF.Floor(amount/1000)*1000;t.Ore-=amount;m.Harvested+=amount;m.Cargo+=amount;if(m.Harvested+.001f>=m.Spec.Volume)EnsureMissionL(m).Emit("harvest");PumpMissionL(m);SyncMissionL();return amount;}
